 const play=async(kind:'body'|'annotations'|'translation'='body',source=poem)=>{if(!source||audioLock.current)return;if(player.current&&audioPoemId===source.id&&audioTarget===kind){if(audioState==='正在播放'){player.current.pause();setAudioState('已暂停');}else{player.current.play();setAudioState('正在播放');}return;}stop();audioLock.current=true;const key=context(),ticket=++audioSeq.current,validAudio=()=>ticket===audioSeq.current&&key===context();setAudioTarget(kind);setAudioPoemId(source.id);setAudioBusy(true);setError('');try{const setting=await api(`/me/ai-settings?family_id=${encodeURIComponent(String(storage.get('family_id')))}`);if(!validAudio())return;const price=setting.audio_yuan_per_10000_characters;if(!price)throw Error('AUDIO_PRICE_NOT_CONFIGURED');const noticeKey=`poem_audio_notice_v4:${key}`;if(!storage.get(noticeKey)){const r=await Taro.showModal({title:'诗词朗读',content:`可分别朗读诗词、注释和译文。首次生成或修改内容后重新生成将使用家庭额度，语音价格为 ¥${price}/万字符；同一版本可重复播放。`,confirmText:'继续'});if(!r.confirm){if(validAudio())stop();return;}if(!validAudio())return;storage.set(noticeKey,true);}const loadPart=async(index:number):Promise<void>=>{if(!validAudio())return;audioLock.current=true;setAudioBusy(true);setAudioState('正在准备朗读');try{const path=kind==='body'?`${base()}/${source.id}/audio`:`${base()}/${source.id}/audio-sections/${kind}/${index}`;const result=await api(path,'POST',{},undefined,120000);if(!validAudio())return;const file=await Taro.downloadFile({url:API_BASE+result.resource_path,header:{Authorization:`Bearer ${storage.get('access_token')}`}});if(!validAudio()||file.statusCode!==200){if(file.tempFilePath)Taro.getFileSystemManager().unlink({filePath:file.tempFilePath,fail:()=>{}});if(validAudio())throw Error('AUDIO_DOWNLOAD_FAILED');return;}if(temp.current)Taro.getFileSystemManager().unlink({filePath:temp.current,fail:()=>{}});temp.current=file.tempFilePath;await Taro.setInnerAudioOption({obeyMuteSwitch:false,mixWithOther:false});if(!validAudio())return;player.current?.destroy();const p=Taro.createInnerAudioContext();player.current=p;p.src=file.tempFilePath;p.onEnded(()=>{if(!validAudio())return;if(index+1<(result.parts||1))void loadPart(index+1);else stop();});p.onError(()=>{if(validAudio()){stop();setError('朗读播放失败，请重试。');}});p.play();setAudioState('正在播放');}catch(e){if(validAudio()){stop();setError(message(e));}}finally{if(validAudio()){audioLock.current=false;setAudioBusy(false);}}};await loadPart(0);}catch(e){if(validAudio()){stop();setError(message(e));}}finally{if(validAudio()){audioLock.current=false;setAudioBusy(false);}}};
 const selectMaterial=async(kind:'camera'|'album'|'file')=>{if(!selectedBook.current){setError('请先创建可编辑的诗本。');return;}if(raw.trim()){const replace=await Taro.showModal({title:'替换现有内容',content:'选择材料会替换当前输入的内容。',confirmText:'继续'});if(!replace.confirm)return;}const consent=await Taro.showModal({title:'后台整理诗词',content:'文件或图片会上传到服务器读取，图片及 PDF 图片页会发送给图片 AI，读取后的文字会发送给文字 AI 整理并使用相应额度。任务提交后可以离开，整理结果请核对后保存。',confirmText:'继续'});if(!consent.confirm)return;const owner=context(),ticket=++seq.current;importing.current=true;setBusy(true);setError('');setInfo('');setMaterialProgress('请选择要导入的材料');try{const material=await selectImportMaterial(kind,()=>{if(valid(ticket,owner))setMaterialProgress('正在读取并上传材料，请保持页面打开。');},'poem');if(!valid(ticket,owner))return;setMaterialProgress('正在提交任务，请保持页面打开。');if(!fileSubmission.current||fileSubmission.current.name!==material.name||fileSubmission.current.data!==material.data)fileSubmission.current={id:eventId(),...material,bookId:selectedBook.current};await api(`${base()}/imports`,'POST',{id:fileSubmission.current.id,name:material.name,base64:material.data,book_id:fileSubmission.current.bookId},undefined,120000);if(valid(ticket,owner)){fileSubmission.current=null;setRaw('');storage.set(`poem-import-draft:${context()}`,'');setInfo('材料上传成功，后台正在读取和整理；可以离开后回来查看进度。');await Taro.navigateTo({url:'/pages/import-records/index'});}}catch(e){if(valid(ticket,owner)&&!isFileCancel(e))setError(`${message(e)}；上传结果不确定时，请先查看整理记录。`);}finally{importing.current=false;if(valid(ticket,owner)){setBusy(false);setMaterialProgress('');}}};
 const loadJobs=async()=>{const owner=context();try{const result=await api(`${base()}/imports`);if(owner===context())setJobs(result.items);}catch(e){if(owner===context())setError(message(e));}};
 useEffect(()=>{if(!visible||mode!=='jobs'||!jobs.some(j=>j.status==='queued'||j.status==='running'))return;const timer=setInterval(()=>void loadJobs(),2000);return()=>clearInterval(timer);},[visible,mode,jobs]);
 const prepare=async()=>{if(!selectedBook.current){setError('请先创建可编辑的诗本。');return;}if(analysisLock.current)return;analysisLock.current=true;const owner=context();try{const chunks=poemAnalysisChunks(raw);const consent=await Taro.showModal({title:'AI 整理诗词',content:`将把材料发送给当前文字 AI 整理，约 ${chunks.length} 段，使用家庭 AI 额度或你配置的个人 AI 服务。整理可在后台继续，请核对结果。`,confirmText:'开始整理'});if(!consent.confirm||owner!==context())return;if(!submission.current||submission.current.raw!==raw)submission.current={id:eventId(),raw,bookId:selectedBook.current};setBusy(true);setError('');setInfo('');setAnalysisProgress('正在提交整理任务');const pending=submission.current;await api(`${base()}/imports`,'POST',{id:pending.id,raw_text:raw,book_id:pending.bookId},undefined,30000);if(owner!==context())return;submission.current=null;setRaw('');storage.set(`poem-import-draft:${context()}`,'');setInfo('任务已提交，可以离开页面；整理完成后回来核对。');await Taro.navigateTo({url:'/pages/import-records/index'});}catch(e){if(owner===context())setError(`${message(e)}；如提交结果不确定，可查看整理记录或重新点击提交。`);}finally{analysisLock.current=false;if(owner===context()){setBusy(false);setAnalysisProgress('');}}};
 const cancelJob=async(id:string)=>{const owner=context(),choice=await Taro.showModal({title:'取消诗词整理',content:'取消后未保存的整理结果和核对修改将被丢弃。已经发出的 AI 请求可能仍会产生费用。',confirmText:'取消任务',cancelText:'继续整理'});if(!choice.confirm||owner!==context())return;setBusy(true);setError('');try{await api(`${base()}/imports/${id}/cancel`,'POST',{});if(owner!==context())return;Taro.removeStorageSync(`poem-review:${owner}:${id}`);if(reviewJob===id){setReviewJob('');setBatch([]);setRaw('');if(reviewId){await Taro.navigateBack();return;}setMode('jobs');}setInfo('任务已取消，未保存的内容已丢弃。');await loadJobs();}catch(e){if(owner===context())setError(message(e));}finally{if(owner===context())setBusy(false);}};
 const openJob=async(id:string)=>{if(jobsOnly){try{await Taro.navigateTo({url:`/pages/poem-review/index?id=${encodeURIComponent(id)}`});}catch(e){setError(message(e));}return;}const owner=context();setBusy(true);setError('');try{const job=await api(`${base()}/imports/${id}`);if(owner!==context())return;if(job.status!=='ready'){setError('任务尚未完成，请刷新查看进度。');return;}const merged=mergePoemAnalysis(job.results),cached=storage.get(`poem-review:${owner}:${id}`);pendingBatch.current=cached?.pending??null;reviewGeneration.current=job.review_generation??0;setRaw(job.raw_text);setReviewJob(id);setBatch((cached&&(cached.pending||((cached.generation??0)===(job.review_generation??0)))?cached.batch:null)??job.review_draft??merged.items.map(({issues,...draft})=>({draft:{...blank(),...draft},issues:issues??[],issuesReviewed:false,key:eventId(),saved:false,locked:false})));setBatchPage(0);setShowRaw(false);setInfo(!merged.items.length?'没有识别到诗词，请更换材料重新使用 AI 录入。':merged.incomplete?'部分内容可能不完整，请核对后保存。':merged.items.every(item=>item.annotations?.trim()&&item.translation?.trim())?'整理完成，已补齐注释和译文，请核对或修改后保存。':'整理完成，请核对或修改后保存。');setMode('review');}catch(e){if(owner===context())setError(message(e));}finally{if(owner===context())setBusy(false);}};
 const persistDraft=(owner:string,id:string,items:BatchItem[])=>{const snapshot=JSON.parse(JSON.stringify(items)),generation=reviewGeneration.current;const work=draftQueue.current.catch(()=>{}).then(async()=>{if(owner!==context())throw Error('SESSION_CHANGED');await api(`${base()}/imports/${id}/draft`,'PUT',{batch:snapshot,expected_batch:generation},undefined,30000);});draftQueue.current=work;return work;};
 useEffect(()=>{if(mode!=='review'||!reviewJob)return;const owner=context(),id=reviewJob;storage.set(`poem-review:${owner}:${id}`,{batch,pending:pendingBatch.current,generation:reviewGeneration.current});const epoch=draftEpoch.current,timer=setTimeout(()=>{if(savingImport.current||pendingBatch.current||draftEpoch.current!==epoch)return;void persistDraft(owner,id,batch).catch(()=>{if(owner===context())setError('核对草稿暂未同步到服务器，请检查网络后重试或继续保存。');});},800);return()=>clearTimeout(timer);},[mode,reviewJob,batch]);
 const changeBatch=(index:number,key:keyof PoemDraft,value:string)=>setBatch(old=>old.map((item,i)=>i===index&&!item.saved&&!item.locked?{...item,draft:{...item.draft,[key]:key==='title'?normalizePoemTitle(value):value},key:eventId()}:item));
 const saveBatch=async()=>{if(savingImport.current)return;if(!reviewJob||!batch.length){setError('请先添加要保存的诗词。');return;}const invalid=batch.findIndex(x=>!normalizePoemTitle(x.draft.title)||!x.draft.body.trim());if(invalid>=0){const fields=[!batch[invalid].draft.title.trim()?'标题':'',!batch[invalid].draft.body.trim()?'正文':''].filter(Boolean).join('、');setBatchPage(Math.floor(invalid/10));setError(`第 ${invalid+1} 首缺少${fields}，请补充后保存。`);return;}const owner=context(),id=reviewJob;if(!pendingBatch.current||pendingBatch.current.job!==id)pendingBatch.current={job:id,request_id:eventId(),expected_batch:reviewGeneration.current,items:batch.slice(0,MAX_POEM_IMPORT_COUNT).map(x=>importFields(x.draft)),remaining_batch:batch.slice(MAX_POEM_IMPORT_COUNT)};const pending=pendingBatch.current;storage.set(`poem-review:${owner}:${id}`,{batch,pending,generation:reviewGeneration.current});savingImport.current=true;draftEpoch.current++;setBusy(true);setError('');try{await draftQueue.current.catch(()=>{});const result=await api(`${base()}/imports/${id}/save`,'POST',{items:pending.items,request_id:pending.request_id,expected_batch:pending.expected_batch,remaining_batch:pending.remaining_batch},undefined,120000);if(owner!==context())return;pendingBatch.current=null;Taro.removeStorageSync(`poem-review:${owner}:${id}`);if(result.remaining_batch?.length){reviewGeneration.current=result.review_generation??reviewGeneration.current+1;setBatch(result.remaining_batch);setBatchPage(0);setInfo(`已导入 ${result.saved_count} 首，跳过重复 ${result.skipped_count??0} 首，还剩 ${result.remaining_batch.length} 首，请继续核对并保存。`);}else{setReviewJob('');setBatch([]);setRaw('');setInfo(`已导入 ${result.total_saved??result.saved_count} 首诗词，跳过重复 ${result.total_skipped??0} 首。`);if(result.total_skipped)await Taro.showModal({title:'导入完成',content:`已导入 ${result.total_saved??result.saved_count} 首，跳过重复 ${result.total_skipped} 首。已有诗词和背诵状态保持不变。`,showCancel:false});if(reviewId){await Taro.navigateBack();}else if(jobsOnly){setMode('jobs');void loadJobs();}else{setMode('list');void load();}}}catch(e){if(owner===context()){const uncertain=['NETWORK_TIMEOUT','NETWORK_REQUEST_FAILED'].includes((e as Error).message)||Number((e as any)?.status)>=500;if(uncertain)setBatch(old=>old.map(item=>({...item,locked:true})));else pendingBatch.current=null;setError(uncertain?'保存结果待确认，请点击保存重试，避免重复导入。':message(e));}}finally{savingImport.current=false;if(owner===context())setBusy(false);}};
 const back=async()=>{if(mode==='review'&&reviewJob&&!pendingBatch.current){const owner=context();setBusy(true);try{await persistDraft(owner,reviewJob,batch);}catch{if(owner===context()){setBusy(false);setError('核对草稿未同步，请检查网络后重试。');}return;}if(owner!==context())return;}seq.current++;setBusy(false);stop();setError('');if(mode==='review'){setReviewJob('');setMode('jobs');void loadJobs();}else if(mode==='jobs'){setMode('list');void load();}else if(mode==='import'){setMode('list');void load();}else if(mode==='chat'){setMode('detail');pending.current=null;}else if(mode==='edit'&&poem)setMode('detail');else if(detailId){void Taro.navigateBack();}else{setPoem(null);setMode('list');void load();}};
 const duplicates=batch.map((item,index)=>{const title=item.draft.title.trim().replace(/[《》\s]/g,''),author=item.draft.author.trim();if(!title)return -1;return batch.findIndex((other,n)=>n<index&&other.draft.title.trim().replace(/[《》\s]/g,'')===title&&(!author||!other.draft.author.trim()||author===other.draft.author.trim()));});
