  {!embedded&&mode!=='list'&&mode!=='detail'&&<View className='poems-header'><View className='title'>{mode==='edit'?'编辑诗词':mode==='chat'?'AI 诗词聊天':mode==='import'?'录入古诗':mode==='review'?'核对诗词':mode==='jobs'?'录入记录':'诗词详情'}</View>{!(detailId&&mode==='edit'&&editOnOpen)&&!(jobsOnly&&mode==='jobs')&&!(entryMode&&mode===entryMode)&&!(reviewId&&mode==='review')&&<Button className='text-action' disabled={busy&&mode==='import'} onClick={back}><Chevron direction='left'/>{mode==='review'?'返回记录':mode==='chat'||mode==='edit'&&poem?'返回详情':'返回列表'}</Button>}</View>}
